# ============================================================
# DATABASE
# ============================================================
def init_db():
    with sqlite3.connect(DB_FILE) as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS telemetry (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp TEXT,
                mode TEXT,
                slave_id INTEGER,
                voltage_v REAL,
                current_a REAL,
                power_kw REAL,
                power_factor REAL,
                energy_kwh REAL,
                water_lpm REAL,
                air_bar REAL,
                gas_m3h REAL,
                steam_bar REAL,
                status TEXT
            )
        """)


init_db()


def get_com_ports():
    if not MODBUS_AVAILABLE:
        return ["Serial libraries unavailable"]
    ports = [port.device for port in serial.tools.list_ports.comports()]
    return ports or ["No COM Port Found"]


# ============================================================
# APPLICATION STATE
# ============================================================
class EMSState:
    def __init__(self):
        self.running = False
        self.mode = "Simulation"
        self.com_port = get_com_ports()[0]
        self.baudrate = 9600
        self.slave_id = 1
        self.poll_interval = 2.0
        self.last_poll = 0.0

        self.voltage = 230.0
        self.current = 12.50
        self.power_kw = 2.76
        self.pf = 0.96
        self.energy_kwh = 2847.0

        self.water_lpm = 125.4
        self.air_bar = 7.10
        self.gas_m3h = 42.0
        self.steam_bar = 8.50

        self.alert_status = "NORMAL"
        self.alert_message = "All electrical and utility parameters are within nominal limits."
        self.timestamps = []
        self.hist_elec = []
        self.hist_water = []
        self.hist_air = []
        self.hist_steam = []


state = EMSState()


# ============================================================
# MODBUS HELPERS
# ============================================================
def read_modbus_registers(client, address, count):
    """Support both newer pymodbus device_id and older slave APIs."""
    try:
        return client.read_holding_registers(address=address, count=count, device_id=int(state.slave_id))
    except TypeError:
        return client.read_holding_registers(address=address, count=count, slave=int(state.slave_id))


def acquire_real_meter_data():
    if not MODBUS_AVAILABLE:
        raise RuntimeError("pyserial and pymodbus are not installed. Install them to use a real meter.")
    if state.com_port in ("No COM Port Found", "Serial libraries unavailable"):
        raise RuntimeError("No serial/COM port is available. Connect the RS-485 adapter and refresh the app.")

    client = ModbusSerialClient(
        port=state.com_port,
        baudrate=int(state.baudrate),
        parity="N",
        stopbits=1,
        bytesize=8,
        timeout=1,
    )
    if not client.connect():
        raise RuntimeError(f"Could not connect to meter on {state.com_port}.")

    try:
        response = read_modbus_registers(client, address=0, count=4)
        if response.isError():
            raise RuntimeError("The meter returned a Modbus error. Check its address and register map.")
        registers = response.registers
        state.voltage = round(registers[0] / 10.0, 1)
        state.current = round(registers[1] / 100.0, 2)
        state.pf = round(registers[2] / 100.0, 2) if registers[2] else 0.95
        state.power_kw = round((state.voltage * state.current * state.pf) / 1000.0, 2)
        # Energy and WAGES values remain unchanged unless their register map is configured.
    finally:
        client.close()


# ============================================================
# DATA ACQUISITION + HISTORIAN
# ============================================================
def poll_data():
    if not state.running:
        return

    now = time.monotonic()
    if now - state.last_poll < float(state.poll_interval):
        return
    state.last_poll = now

    try:
        if state.mode == "Simulation":
            state.voltage = round(random.uniform(226.0, 236.0), 1)
            state.current = round(random.uniform(11.0, 18.5), 2)
            state.pf = round(random.uniform(0.93, 0.99), 2)
            state.power_kw = round(state.voltage * state.current * state.pf / 1000.0, 2)
            state.energy_kwh = round(state.energy_kwh + state.power_kw * (state.poll_interval / 3600.0), 3)
            state.water_lpm = round(random.uniform(115.0, 145.0), 1)
            state.air_bar = round(random.uniform(6.4, 7.8), 2)
            state.gas_m3h = round(random.uniform(38.0, 48.0), 1)
            state.steam_bar = round(random.uniform(7.8, 9.2), 2)
        else:
            acquire_real_meter_data()

        if state.voltage > 245.0 or state.voltage < 210.0:
            state.alert_status = "CRITICAL"
            state.alert_message = f"Critical voltage deviation: {state.voltage:.1f} V is outside the 210–245 V operating band."
        elif state.pf < 0.95:
            state.alert_status = "WARNING"
            state.alert_message = f"Power factor is {state.pf:.2f}, below the target threshold of 0.95."
        else:
            state.alert_status = "NORMAL"
            state.alert_message = "All electrical and utility parameters are within nominal limits."

        full_timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with sqlite3.connect(DB_FILE) as conn:
            conn.execute("""
                INSERT INTO telemetry (
                    timestamp, mode, slave_id, voltage_v, current_a, power_kw,
                    power_factor, energy_kwh, water_lpm, air_bar, gas_m3h,
                    steam_bar, status
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (
                full_timestamp, state.mode, state.slave_id, state.voltage,
                state.current, state.power_kw, state.pf, state.energy_kwh,
                state.water_lpm, state.air_bar, state.gas_m3h,
                state.steam_bar, state.alert_status,
            ))

        state.timestamps.append(datetime.now().strftime("%H:%M:%S"))
        state.hist_elec.append(round(state.power_kw * 25, 1))
        state.hist_water.append(state.water_lpm)
        state.hist_air.append(round(state.air_bar * 10, 1))
        state.hist_steam.append(round(state.steam_bar * 12, 1))
        for history in (state.timestamps, state.hist_elec, state.hist_water, state.hist_air, state.hist_steam):
            if len(history) > 20:
                history.pop(0)

        refresh_ui()
    except Exception as error:
        state.alert_status = "ERROR"
        state.alert_message = str(error)
        refresh_ui()
        state.running = False
        start_btn.set_text("START ACQUISITION")
        start_btn.props("color=primary icon=play_arrow")
        status_badge.set_text("CONNECTION ERROR")
        status_badge.props("color=negative")
        ui.notify(str(error), type="negative")


# ============================================================
# EXCEL EXPORT
# ============================================================
def export_excel():
    with sqlite3.connect(DB_FILE) as conn:
        rows = conn.execute("""
            SELECT timestamp, mode, slave_id, voltage_v, current_a, power_kw,
                   power_factor, energy_kwh, water_lpm, air_bar, gas_m3h,
                   steam_bar, status
            FROM telemetry ORDER BY id DESC LIMIT 5000
        """).fetchall()

    if not rows:
        ui.notify("No logged data available yet. Start acquisition first.", type="warning")
        return

    filename = f"ProEnergy_EMS_Report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx"
    workbook = openpyxl.Workbook()
    sheet = workbook.active
    sheet.title = "Power and WAGES Data"
    headers = [
        "Timestamp", "Mode", "Slave ID", "Voltage (V)", "Current (A)",
        "Active Power (kW)", "Power Factor", "Total Energy (kWh)",
        "Water Flow (L/min)", "Air Pressure (bar)", "Gas Flow (m3/hr)",
        "Steam Pressure (bar)", "Alert Status",
    ]
    sheet.append(headers)
    for cell in sheet[1]:
        cell.font = openpyxl.styles.Font(bold=True, color="FFFFFF")
        cell.fill = openpyxl.styles.PatternFill("solid", fgColor="174C3C")
    for row in rows:
        sheet.append(list(row))
    sheet.freeze_panes = "A2"
    sheet.auto_filter.ref = sheet.dimensions
    for column in sheet.columns:
        width = min(max(max(len(str(cell.value or "")) for cell in column) + 2, 12), 28)
        sheet.column_dimensions[column[0].column_letter].width = width
    workbook.save(filename)
    ui.download(filename)
    ui.notify(f"Exported {len(rows)} records successfully.", type="positive")


