# ============================================================
# UI ACTIONS / REFRESH
# ============================================================
def toggle_run():
    state.running = not state.running
    if state.running:
        state.last_poll = 0.0
        start_btn.set_text("Stop acquisition")
        start_btn.props("color=negative icon=stop")
        status_badge.set_text("LIVE POLLING ACTIVE")
        status_badge.props("color=positive")
        poll_data()
    else:
        start_btn.set_text("Start acquisition")
        start_btn.props("color=primary icon=play_arrow")
        status_badge.set_text("SYSTEM STANDBY")
        status_badge.props("color=grey")


def refresh_ui():
    lbl_volt.set_text(f"{state.voltage:.1f}")
    lbl_curr.set_text(f"{state.current:.2f}")
    lbl_kw.set_text(f"{state.power_kw:.2f}")
    lbl_pf.set_text(f"{state.pf:.2f}")
    lbl_kwh.set_text(f"{state.energy_kwh:.2f}")
    lbl_water.set_text(f"{state.water_lpm:.1f}")
    lbl_air.set_text(f"{state.air_bar:.2f}")
    lbl_gas.set_text(f"{state.gas_m3h:.1f}")
    lbl_steam.set_text(f"{state.steam_bar:.2f}")
    clock_label.set_text(datetime.now().strftime("%d %b %Y  ·  %H:%M:%S"))

    alert_text.set_text(state.alert_message)
    if state.alert_status == "NORMAL":
        alert_card.classes(replace="alert-panel w-full items-center gap-3 no-wrap")
        alert_card.style("background:#f0f7f2;border-color:#dcebe1")
        alert_icon.name = "check_circle"
        alert_icon.style("color:#23845b")
    elif state.alert_status == "WARNING":
        alert_card.classes(replace="alert-panel w-full items-center gap-3 no-wrap")
        alert_card.style("background:#fff8eb;border-color:#f0dfbd")
        alert_icon.name = "warning_amber"
        alert_icon.style("color:#b78025")
    else:
        alert_card.classes(replace="alert-panel w-full items-center gap-3 no-wrap")
        alert_card.style("background:#fff1f1;border-color:#f0d0d0")
        alert_icon.name = "error"
        alert_icon.style("color:#c44747")

    chart.options["xAxis"]["data"] = list(state.timestamps)
    for index, values in enumerate((state.hist_elec, state.hist_water, state.hist_air, state.hist_steam)):
        chart.options["series"][index]["data"] = list(values)
    chart.update()


